-- Wardogs advisor Phase 1a -- BALLISTICS DATA LOAD. Operator runs this AFTER the schema DDL.
-- Source: Swoleguy ballistics xlsx (STATS/FULL STK/STK/Armor Break/TTK). Creator-sourced,
-- attributed, verified=false. Scoped to game_slug=wardogs. Re-runnable (scoped DELETE first).
-- Semicolon-safe: each statement ends with one terminator, NO semicolons inside strings.
-- Row math: 30 weapons x 8 body_parts x 3 ammo x 5 tiers = 3600 ballistics rows, 450 ttk rows.

delete from wardogs_ballistics where game_slug = 'wardogs';
delete from wardogs_ttk where game_slug = 'wardogs';





























































-- Cost/unlock DATA (honest, tiered). ONLY Deagle unlock_career_level=85 is Bulkhead-confirmed
-- (Season 1 changelog, Tier 1). credit_cost stays NULL (no first-party price list -- Tier 4).
-- Other per-weapon class-unlock levels are community/beta-attributed only -> DEFERRED (see report).
update weapon_stats set unlock_career_level = 85,
  notes = coalesce(notes,'') || ' | unlock_career_level 85: Bulkhead Season 1 changelog (Tier 1), 2026-09-09'
  where game_slug = 'wardogs' and name = 'Deagle' and coalesce(notes,'') not like '%unlock_career_level 85%';
